@rule("s7", "s9", otherwise="NotMentioned")
def auditor_auditee_identity():
    return "Auditor" if "Auditor" in "Name incorporated/registered under the….….. Name of the Act having its registered/corporate office at ………………(herein referred to as “Auditor”" else "Auditee"

@rule("s10", "s11", otherwise="NotMentioned")
def auditor_empanelment():
    return "empanelled by the Indian Computer Emergency Response Team (hereinafter CERT-IN)" in "A.Auditor is a services organization empanelled by the Indian Computer Emergency Response Team (hereinafter CERT-IN) under Department of Electronics & IT, for auditing, including vulnerability assessment and penetration testing of computer systems , networks, computer resources & applications of various agencies or departments of the Government, critical infrastructure organizations and those in other sectors of Indian economy vide communication No…………dated…………."

@rule("s16", "s17", otherwise="NotMentioned")
def confidential_information():
    return "Confidential Information" in "The term “Confidential Information” shall include, without limitation, all information and materials, furnished by either Party to the other in connection with Auditee products and services including information transmitted in writing, orally, visually, (e.g. video terminal display) or on magnetic media, and including all proprietary information, customer & prospect lists, trade secrets, trade names or proposed trade names, methods and procedures of operation, business or marketing plans, licensed document know-how, ideas, concepts, designs, drawings, flow charts, diagrams, quality manuals, checklists, guidelines, processes, formulae, source code materials, specifications, programs, software packages, codes and other intellectual property relating to Auditee products and services. Results of any information security audits, tests, analysis, extracts or usages carried out by the Auditor in connection with the Auditee’s products and/or services, IT infrastructure, etc. shall also be considered Confidential Information."

@rule("s25", "s26", otherwise="NotMentioned")
def data_handling():
    return "storage, processing, analysis or handling" in "Auditor shall use only the best possible secure methodology to avoid confidentiality breach, while handling audit related data for the purpose of storage, processing, transit or analysis including sharing of information with auditee."

@rule("s39", "s40", otherwise="NotMentioned")
def intellectual_property():
    return "No license to a party, under any trademark, patent, copyright, design right, mask work protection right, or any other intellectual property right is either granted or implied by the conveying of Confidential Information to such party." in "No license to a party, under any trademark, patent, copyright, design right, mask work protection right, or any other intellectual property right is either granted or implied by the conveying of Confidential Information to such party."

@rule("s52", "s53", otherwise="NotMentioned")
def agreement_term():
    return "This Agreement shall come into force on the date of its signing by both the parties and shall be valid up to ……… year." in "This Agreement shall come into force on the date of its signing by both the parties and shall be valid up to ……… year."

@rule("s70", "s71", otherwise="NotMentioned")
def witnesses():
    return "WITNESSES:" in "WITNESSES:"

@rule("s72", "s70", otherwise="NotMentioned")
def witness_names():
    return "1." in "1."

query = "Receiving Party shall not reverse engineer any objects which embody Disclosing Party's Confidential Information." in "Receiving Party shall not reverse engineer any objects which embody Disclosing Party's Confidential Information."
